package com.focusflow.api.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.web.bind.MethodArgumentNotValidException; import java.time.*; import java.util.*; @RestControllerAdvice public class ApiExceptionHandler {record Error(String message,int status,Instant timestamp){} @ExceptionHandler(ResponseStatusException.class) ResponseEntity<Error> status(ResponseStatusException e){return ResponseEntity.status(e.getStatusCode()).body(new Error(e.getReason(),e.getStatusCode().value(),Instant.now()));}@ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Error> invalid(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(new Error(e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+" "+x.getDefaultMessage()).orElse("Invalid request"),400,Instant.now()));} }
